		return "", err
	}
	if !ok {
		return "", fmt.Errorf("missing %s", key)
	}
	return value, nil
}

// [🧰semiorepo⌨️cli💻main🔖types🔖mcp🔖args🛠️getintarg](semiorepo://p/i/semio-repo/b/b/cli/f/main.go/s/Types/s/Mcp/s/Args/d/i/getIntArg)
