	return int(number), true, nil
}

// [🧰semiorepo⌨️cli💻main🔖types🔖mcp🔖args🛠️requireintarg](semiorepo://p/i/semio-repo/b/b/cli/f/main.go/s/Types/s/Mcp/s/Args/d/i/requireIntArg)
