// [🧰semiorepo⌨️cli💻main🔖types🔖mcp🔖args🛠️getstringslicearg](semiorepo://p/i/semio-repo/b/b/cli/f/main.go/s/Types/s/Mcp/s/Args/d/i/getStringSliceArg)
func getStringSliceArg(args map[string]interface{}, key string) ([]string, bool, error) {
	value, ok := args[key]
	if !ok {
		return nil, false, nil
	}
	list, ok := value.([]interface{})
	if !ok || len(list) == 0 {
		return nil, true, fmt.Errorf("invalid %s", key)
	}
	result := make([]string, 0, len(list))
	for _, item := range list {
		str, ok := item.(string)
		if !ok || str == "" {
			return nil, true, fmt.Errorf("invalid %s", key)
		}
		result = append(result, str)
	}
	return result, true, nil
}

