// [🧰semiorepo⌨️cli💻main🔖types🔖mcp🔖handlers🛠️renderprompttemplate](semiorepo://p/i/semio-repo/b/b/cli/f/main.go/s/Types/s/Mcp/s/Handlers/d/i/renderPromptTemplate)
// renderPromptTemplate holds the data fields for a renderPromptTemplate record.
// renderPromptTemplate MUST perform the renderPromptTemplate operation.
func renderPromptTemplate(name string, data map[string]string) (string, error) {
	path := GetRepoMetaPath(filepath.Join("💬", "📋", name+".tpl"))
	content, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	tmpl, err := template.New(name).Funcs(sprig.TxtFuncMap()).Parse(string(content))
	if err != nil {
		return "", err
	}
	var out strings.Builder
	if err := tmpl.Execute(&out, data); err != nil {
		return "", err
	}
	return out.String(), nil
}

